#include <stdio.h>

int main() {
    char s[] = "hello big world";
    int write = 0;
    for (int read = 0; s[read] != '\0'; read++) {
        if (s[read] != ' ') {
            s[write++] = s[read];
        }
    }
    s[write] = '\0';
    printf("%s\n", s);
    return 0;
}
